import { Component, OnInit, OnDestroy, HostListener } from '@angular/core';
import { Router } from '@angular/router';
import { AssetService } from '../../services/asset.service';

export interface ReturnRecord {
  assetName:      string;
  assetTag:       string;
  classification: string;
  total:          number;
  returnType:     string;
  returnTo:       string;
  returnDate:     string;
  department:     string;
}

const PAGE_SIZE = 8;

@Component({
  selector: 'app-return-log',
  templateUrl: './return-log.component.html',
  styleUrls: ['./return-log.component.scss'],
})
export class ReturnLogComponent implements OnInit, OnDestroy {

  assetsDropdownOpen = false;
  sidebarOpen        = false;
  isLoading          = true;
  apiError: string | null = null;

  // ── Filter ───────────────────────────────────────────────────────────────────
  filterOpen = false;
  filterClassifications: string[] = [];
  readonly classificationFilterOptions = ['Asset', 'Component', 'Consumable', 'Accessory'];

  // ── View ─────────────────────────────────────────────────────────────────────
  selectedRecord: ReturnRecord | null = null;

  // ── Department tabs (built from API data) ────────────────────────────────────
  departments: string[] = [];
  activeDept  = '';

  searchQuery = '';
  currentPage = 1;

  // ── Form (detail panel) ───────────────────────────────────────────────────────
  formAssetName      = '';
  formAssetTag       = '';
  formClassification = '';
  formTotal: number | null = null;
  formReturnType     = '';
  formReturnTo       = '';
  formReturnDate     = '';

  classificationOptions = ['Asset', 'Component', 'Consumable', 'Accessory'];
  returnTypeOptions     = ['Permanent Return', 'Temporary Return', 'Damaged Return', 'Lost Report'];
  returnToOptions       = ['IT Department', 'Admin Office', 'Library', 'Lab Store', 'Principal Office'];

  // ── Data ─────────────────────────────────────────────────────────────────────
  allRecords: ReturnRecord[] = [];

  // ── Computed ─────────────────────────────────────────────────────────────────
  get filteredRecords(): ReturnRecord[] {
    const q = this.searchQuery.toLowerCase();
    return this.allRecords.filter(r => {
      const matchesDept  = !this.activeDept || r.department === this.activeDept;
      const matchSearch  = !q || r.assetName.toLowerCase().includes(q)
                              || r.assetTag.toLowerCase().includes(q)
                              || r.returnTo.toLowerCase().includes(q);
      const matchClass   = this.filterClassifications.length === 0
                        || this.filterClassifications.includes(r.classification);
      return matchesDept && matchSearch && matchClass;
    });
  }

  get totalPages(): number { return Math.max(1, Math.ceil(this.filteredRecords.length / PAGE_SIZE)); }

  get pagedRecords(): ReturnRecord[] {
    const start = (this.currentPage - 1) * PAGE_SIZE;
    return this.filteredRecords.slice(start, start + PAGE_SIZE);
  }

  get visiblePages(): number[] {
    const total = this.totalPages;
    const cur   = this.currentPage;
    if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
    const pages: number[] = [1, 2, 3];
    if (cur > 4) pages.push(-1);
    if (cur > 3 && cur < total - 2) pages.push(cur);
    pages.push(-1);
    pages.push(total - 2, total - 1, total);
    return [...new Set(pages)].filter((p, idx, arr) => {
      if (p === -1) return arr[idx - 1] !== -1;
      return true;
    });
  }

  constructor(private router: Router, private assetService: AssetService) {}

  ngOnInit(): void  { this.loadReturnLogs(); }
  ngOnDestroy(): void {}

  private loadReturnLogs(): void {
    this.isLoading = true;
    this.apiError  = null;

    this.assetService.getReturnLogs().subscribe({
      next: (response: any) => {
        // Shape: { statusCode, type, responseData: { data: { assets: [] } } }
        const raw: any[] = response?.responseData?.data?.assets ?? [];

        this.allRecords = raw.map(item => ({
          assetName:      item.assetName  ?? '—',
          assetTag:       item.assetName  ?? '—',   // no tag in response, use name as identifier
          classification: 'Asset',                   // API doesn't return this field, default to Asset
          total:          item.total      ?? 0,
          returnType:     item.returnType ?? '—',
          returnTo:       item.issuedFor  ?? '—',
          returnDate:     item.returnDate
                            ? new Date(item.returnDate).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
                            : '—',
          department:     item.category  ?? 'Other'
        }));

        // Build dept tabs dynamically from categories in data
        this.departments = [...new Set(this.allRecords.map(r => r.department))];
        this.activeDept  = this.departments[0] ?? '';
        this.isLoading   = false;
      },
      error: (err) => {
        console.error('Failed to load return logs:', err);
        this.apiError = 'Could not load return log data from the server.';
        this.isLoading = false;
      }
    });
  }

  @HostListener('document:click')
  onDocumentClick(): void { this.sidebarOpen = false; this.filterOpen = false; }

  // ── Filter ───────────────────────────────────────────────────────────────────
  toggleFilterPanel(event: Event): void { event.stopPropagation(); this.filterOpen = !this.filterOpen; }

  toggleClassFilter(c: string): void {
    const i = this.filterClassifications.indexOf(c);
    if (i === -1) this.filterClassifications.push(c);
    else this.filterClassifications.splice(i, 1);
    this.currentPage = 1;
  }

  clearFilters(): void { this.filterClassifications = []; this.currentPage = 1; }

  // ── Export ───────────────────────────────────────────────────────────────────
  exportCSV(): void {
    const headers = ['Name', 'Category', 'Total', 'Return Type', 'Returned To', 'Return Date'];
    const csv = [
      headers.join(','),
      ...this.filteredRecords.map(r =>
        [r.assetName, r.department, r.total, r.returnType, r.returnTo, r.returnDate].join(',')
      )
    ].join('\n');
    this.downloadCSV(csv, `return-log-${this.activeDept}.csv`);
  }

  private downloadCSV(content: string, filename: string): void {
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url; a.download = filename; a.click();
    URL.revokeObjectURL(url);
  }

  // ── Navigation ───────────────────────────────────────────────────────────────
  setDept(dept: string): void {
    this.activeDept     = dept;
    this.searchQuery    = '';
    this.currentPage    = 1;
    this.selectedRecord = null;
  }

  prevPage(): void { if (this.currentPage > 1) this.currentPage--; }
  nextPage(): void { if (this.currentPage < this.totalPages) this.currentPage++; }
  goToPage(p: number): void { this.currentPage = p; }

  goToDashboard(): void  { this.router.navigate(['/']); }
  goToViewAssets(): void { this.router.navigate(['/assets/view']); }
  goToIssueAsset(): void { this.router.navigate(['/assets/issue']); }
  goToReports(): void    { this.router.navigate(['/assets/reports']); }

  // ── Row click ─────────────────────────────────────────────────────────────────
  openDetail(row: ReturnRecord): void {
    this.selectedRecord     = row;
    this.formAssetName      = row.assetName;
    this.formAssetTag       = row.assetTag;
    this.formClassification = row.classification;
    this.formTotal          = row.total;
    this.formReturnType     = row.returnType;
    this.formReturnTo       = row.returnTo;
    this.formReturnDate     = row.returnDate;
  }

  closeDetail(): void { this.selectedRecord = null; }

  onSubmit(): void {
    if (!this.selectedRecord) return;
    this.selectedRecord.returnType = this.formReturnType;
    this.selectedRecord.returnTo   = this.formReturnTo;
    this.selectedRecord.returnDate = this.formReturnDate;
    this.closeDetail();
  }

  getClassClass(c: string): string {
    const map: Record<string, string> = {
      'Asset': 'class-asset', 'Component': 'class-component',
      'Consumable': 'class-consumable', 'Accessory': 'class-accessory'
    };
    return map[c] ?? 'class-asset';
  }
}
<div class="flex flex-col h-screen w-screen overflow-hidden bg-[#F0F2F5] font-inter text-xs">

  <!-- TOP HEADER (full width, like USYS) -->
  <header class="h-12 bg-white border-b border-slate-200 flex items-center px-4 flex-shrink-0 gap-4">
    <div class="flex flex-col leading-none w-36 flex-shrink-0">
      <span class="text-[8px] text-slate-400 uppercase tracking-widest">Kristu Jayanti</span>
      <img src="assets/usys-logo.png" alt="USYS" class="h-5 object-contain object-left mt-0.5" />
    </div>
    <div class="flex-1 flex justify-center">
      <img src="assets/kjc-banner.png" alt="Kristu Jayanti University" class="h-7 object-contain" />
    </div>
    <span class="text-[10px] text-slate-400 w-36 text-right flex-shrink-0">Hi, Abin Xavier</span>
  </header>

  <!-- BELOW HEADER: sidebar + content -->
  <div class="flex flex-1 overflow-hidden">

  <!-- SIDEBAR -->
  <aside class="bg-white border-r border-slate-200 flex flex-col flex-shrink-0 transition-all duration-200 overflow-hidden"
    [class.w-12]="!sidebarOpen" [class.w-44]="sidebarOpen" (click)="$event.stopPropagation()">

    <!-- Collapsed: icon button -->
    <div *ngIf="!sidebarOpen" class="flex flex-col items-center py-3">
      <button class="flex flex-col items-center gap-1 w-10 py-2 rounded-lg bg-black text-white hover:bg-slate-800 transition-colors duration-150"
        (click)="sidebarOpen = true">
        <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-4 h-4">
          <path stroke-linecap="round" stroke-linejoin="round" d="M20.25 7.5l-.625 10.632a2.25 2.25 0 0 1-2.247 2.118H6.622a2.25 2.25 0 0 1-2.247-2.118L3.75 7.5M10 11.25h4M3.375 7.5h17.25c.621 0 1.125-.504 1.125-1.125v-1.5c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v1.5c0 .621.504 1.125 1.125 1.125Z"/>
        </svg>
        <span class="text-[8px] font-medium leading-none">Assets</span>
      </button>
    </div>

    <!-- Expanded: full panel -->
    <ng-container *ngIf="sidebarOpen">
      <div class="flex items-center justify-between px-3 py-3 border-b border-slate-100">
        <span class="text-xs font-semibold text-slate-800 whitespace-nowrap">Assets</span>
        <button class="text-slate-400 hover:text-slate-700 transition-colors" (click)="sidebarOpen = false">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-3.5 h-3.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5"/>
          </svg>
        </button>
      </div>
      <div class="px-3 py-2 border-b border-slate-100">
        <div class="flex items-center gap-1.5 bg-slate-50 border border-slate-200 rounded-md px-2 h-7">
          <svg fill="none" viewBox="0 0 24 24" stroke="#AEAEAE" stroke-width="2" class="w-3 h-3 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"/>
          </svg>
          <span class="text-[10px] text-slate-400">Search menu</span>
        </div>
      </div>
      <nav class="flex flex-col px-2 py-2 gap-0.5">
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToDashboard()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M3.75 6A2.25 2.25 0 0 1 6 3.75h2.25A2.25 2.25 0 0 1 10.5 6v2.25a2.25 2.25 0 0 1-2.25 2.25H6a2.25 2.25 0 0 1-2.25-2.25V6ZM3.75 15.75A2.25 2.25 0 0 1 6 13.5h2.25a2.25 2.25 0 0 1 2.25 2.25V18a2.25 2.25 0 0 1-2.25 2.25H6A2.25 2.25 0 0 1 3.75 18v-2.25ZM13.5 6a2.25 2.25 0 0 1 2.25-2.25H18A2.25 2.25 0 0 1 20.25 6v2.25A2.25 2.25 0 0 1 18 10.5h-2.25a2.25 2.25 0 0 1-2.25-2.25V6ZM13.5 15.75a2.25 2.25 0 0 1 2.25-2.25H18a2.25 2.25 0 0 1 2.25 2.25V18A2.25 2.25 0 0 1 18 20.25h-2.25A2.25 2.25 0 0 1 13.5 18v-2.25Z"/>
          </svg>
          Dashboard
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToViewAssets()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M8.25 6.75h12M8.25 12h12m-12 5.25h12M3.75 6.75h.007v.008H3.75V6.75Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0ZM3.75 12h.007v.008H3.75V12Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm-.375 5.25h.007v.008H3.75v-.008Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z"/>
          </svg>
          View Assets
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToIssueAsset()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M15.75 6a3.75 3.75 0 1 1-7.5 0 3.75 3.75 0 0 1 7.5 0ZM4.501 20.118a7.5 7.5 0 0 1 14.998 0A17.933 17.933 0 0 1 12 21.75c-2.676 0-5.216-.584-7.499-1.632Z"/>
          </svg>
          Issue Asset
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left bg-blue-600 text-white whitespace-nowrap">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M9 15 3 9m0 0 6-6M3 9h12a6 6 0 0 1 0 12h-3"/>
          </svg>
          Return Log
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToReports()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M3 13.125C3 12.504 3.504 12 4.125 12h2.25c.621 0 1.125.504 1.125 1.125v6.75C7.5 19.496 6.996 20 6.375 20h-2.25A1.125 1.125 0 0 1 3 18.875v-5.75Zm7.5-5.25c0-.621.504-1.125 1.125-1.125h2.25c.621 0 1.125.504 1.125 1.125v12c0 .621-.504 1.125-1.125 1.125h-2.25A1.125 1.125 0 0 1 10.5 20.875v-13Zm7.5-5.25c0-.621.504-1.125 1.125-1.125h2.25c.621 0 1.125.504 1.125 1.125v17.25c0 .621-.504 1.125-1.125 1.125h-2.25A1.125 1.125 0 0 1 18 20.875V2.625Z"/>
          </svg>
          Reports
        </button>
      </nav>
    </ng-container>
  </aside>

  <!-- MAIN -->
  <div class="flex flex-col flex-1 overflow-hidden">
    <div class="flex-1 overflow-y-auto p-4">
      <!-- Page header -->
      <div class="mb-4">
        <div class="flex items-center gap-1.5 text-[10px] text-slate-400 mb-1">
          <span>Apps</span>
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-2.5 h-2.5"><path stroke-linecap="round" stroke-linejoin="round" d="m8.25 4.5 7.5 7.5-7.5 7.5"/></svg>
          <span class="text-blue-600 font-medium">Asset Management</span>
        </div>
        <h1 class="text-sm font-semibold text-slate-800 mb-3">Asset Management</h1>
        <div class="flex gap-3">
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToDashboard()">
            <span class="text-xs font-semibold">Dashboard</span>
            <span class="text-[10px] text-slate-400 mt-1">Overview &amp; Summary</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToViewAssets()">
            <span class="text-xs font-semibold">View Assets</span>
            <span class="text-[10px] text-slate-400 mt-1">Browse all assets</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToIssueAsset()">
            <span class="text-xs font-semibold">Issue Asset</span>
            <span class="text-[10px] text-slate-400 mt-1">Assign to a user</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-blue-700 text-white w-44 cursor-pointer shadow-sm">
            <span class="text-xs font-bold">Return Log</span>
            <span class="text-[10px] text-blue-200 mt-1">Track returns</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToReports()">
            <span class="text-xs font-semibold">Reports</span>
            <span class="text-[10px] text-slate-400 mt-1">Asset analytics</span>
          </div>
        </div>
      </div>

      <!-- Main card -->
      <div class="bg-white rounded-xl shadow-sm overflow-hidden">

        <!-- Dept tabs -->
        <div class="flex border-b border-slate-200 px-4 overflow-x-auto">
          <button *ngFor="let dept of departments"
            class="px-3 py-2.5 text-[11px] font-medium border-b-2 -mb-px whitespace-nowrap transition-colors duration-150"
            [class.border-slate-800]="activeDept === dept"
            [class.text-slate-800]="activeDept === dept"
            [class.border-transparent]="activeDept !== dept"
            [class.text-slate-400]="activeDept !== dept"
            [class.hover:text-slate-600]="activeDept !== dept"
            (click)="setDept(dept)">{{ dept }}</button>
        </div>

        <!-- Toolbar -->
        <div class="flex items-center gap-2 px-4 py-2.5 border-b border-slate-100">
          <div class="flex items-center gap-1.5 bg-slate-50 border border-slate-200 rounded-lg px-3 h-7 flex-1 max-w-xs">
            <svg fill="none" viewBox="0 0 24 24" stroke="#AEAEAE" stroke-width="2" class="w-3 h-3 flex-shrink-0">
              <path stroke-linecap="round" stroke-linejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"/>
            </svg>
            <input class="flex-1 bg-transparent text-xs text-slate-700 outline-none placeholder:text-slate-400" type="text"
              placeholder="Search by name, ID..." [(ngModel)]="searchQuery"/>
          </div>
          <button class="flex items-center gap-1.5 h-7 px-3 rounded-lg border border-slate-200 text-[10px] font-medium text-slate-600 hover:border-blue-400 hover:text-blue-600 transition-all duration-150 active:scale-95"
            (click)="exportCSV()">
            <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3 h-3">
              <path stroke-linecap="round" stroke-linejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M16.5 12 12 16.5m0 0L7.5 12m4.5 4.5V3"/>
            </svg>
            Export
          </button>
          <!-- Filter button + dropdown -->
          <div class="relative" (click)="$event.stopPropagation()">
            <button class="flex items-center gap-1.5 h-7 px-3 rounded-lg border text-[10px] font-medium transition-all duration-150 active:scale-95"
              [class.border-blue-500]="filterOpen || filterClassifications.length > 0"
              [class.bg-blue-50]="filterOpen || filterClassifications.length > 0"
              [class.text-blue-700]="filterOpen || filterClassifications.length > 0"
              [class.border-slate-200]="!filterOpen && filterClassifications.length === 0"
              [class.text-slate-600]="!filterOpen && filterClassifications.length === 0"
              (click)="toggleFilterPanel($event)">
              <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3 h-3">
                <path stroke-linecap="round" stroke-linejoin="round" d="M12 3c2.755 0 5.455.232 8.083.678.533.09.917.556.917 1.096v1.044a2.25 2.25 0 0 1-.659 1.591l-5.432 5.432a2.25 2.25 0 0 0-.659 1.591v2.927a2.25 2.25 0 0 1-1.244 2.013L9.75 21v-6.568a2.25 2.25 0 0 0-.659-1.591L3.659 7.409A2.25 2.25 0 0 1 3 5.818V4.774c0-.54.384-1.006.917-1.096A48.32 48.32 0 0 1 12 3Z"/>
              </svg>
              Filter
              <span *ngIf="filterClassifications.length > 0" class="ml-0.5 bg-blue-600 text-white text-[9px] font-bold rounded-full w-4 h-4 flex items-center justify-center">{{ filterClassifications.length }}</span>
            </button>
            <!-- Filter dropdown -->
            <div *ngIf="filterOpen" class="absolute top-full right-0 mt-1 w-44 bg-white border border-slate-200 rounded-xl shadow-lg z-50 py-1">
              <div class="flex items-center justify-between px-3 py-1.5 border-b border-slate-100">
                <span class="text-[10px] font-semibold text-slate-500 uppercase tracking-wide">Classification</span>
                <button class="text-[10px] text-blue-600 hover:text-blue-800 font-medium" (click)="clearFilters()">Clear</button>
              </div>
              <div *ngFor="let c of classificationFilterOptions"
                class="flex items-center gap-2 px-3 py-2 hover:bg-blue-50 cursor-pointer transition-colors"
                (click)="toggleClassFilter(c)">
                <div class="w-3.5 h-3.5 rounded border flex items-center justify-center flex-shrink-0 transition-all"
                  [class.bg-blue-600]="filterClassifications.includes(c)"
                  [class.border-blue-600]="filterClassifications.includes(c)"
                  [class.border-slate-300]="!filterClassifications.includes(c)">
                  <svg *ngIf="filterClassifications.includes(c)" fill="none" viewBox="0 0 24 24" stroke="white" stroke-width="3" class="w-2.5 h-2.5">
                    <path stroke-linecap="round" stroke-linejoin="round" d="M4.5 12.75l6 6 9-13.5"/>
                  </svg>
                </div>
                <span class="text-xs text-slate-700" [class.font-medium]="filterClassifications.includes(c)" [class.text-blue-700]="filterClassifications.includes(c)">{{ c }}</span>
              </div>
            </div>
          </div>
        </div>

        <!-- Table header -->
        <div class="grid return-cols px-4 py-2 bg-slate-50 border-b border-slate-200">
          <span class="text-[10px] text-slate-400 font-medium">Name</span>
          <span class="text-[10px] text-slate-400 font-medium">Classification</span>
          <span class="text-[10px] text-slate-400 font-medium">Total</span>
          <span class="text-[10px] text-slate-400 font-medium">Return Type</span>
          <span class="text-[10px] text-slate-400 font-medium">Return To</span>
          <span class="text-[10px] text-slate-400 font-medium">Return Date</span>
        </div>

        <!-- Empty state -->
        <div *ngIf="pagedRecords.length === 0" class="flex flex-col items-center justify-center py-12 gap-2 text-slate-400">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5" class="w-8 h-8">
            <path stroke-linecap="round" stroke-linejoin="round" d="M9 15 3 9m0 0 6-6M3 9h12a6 6 0 0 1 0 12h-3"/>
          </svg>
          <span class="text-xs">No return records for {{ activeDept }}.</span>
        </div>

        <!-- Rows -->
        <ng-container *ngFor="let row of pagedRecords; let i = index">
          <div class="grid return-cols px-4 py-2.5 border-b border-slate-50 last:border-0 cursor-pointer transition-colors hover:bg-blue-50"
            [class.bg-white]="i % 2 === 0" [class.bg-slate-50]="i % 2 !== 0">
            <div class="flex flex-col gap-0.5">
              <span class="text-xs font-medium text-slate-800">{{ row.assetName }}</span>
              <span class="text-[10px] text-slate-400">{{ row.assetTag }}</span>
            </div>
            <span>
              <span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-medium bg-slate-100 text-slate-700" [ngClass]="getClassClass(row.classification)">{{ row.classification }}</span>
            </span>
            <span class="text-xs text-slate-600">{{ row.total }}</span>
            <span class="text-xs text-slate-400">{{ row.returnType || '—' }}</span>
            <span class="text-xs text-slate-400">{{ row.returnTo || '—' }}</span>
            <span class="text-xs text-slate-400">{{ row.returnDate || '—' }}</span>
          </div>
        </ng-container>

        <!-- Pagination -->
        <div class="flex items-center justify-between px-4 py-2.5 border-t border-slate-100">
          <button class="flex items-center gap-1.5 h-7 px-3 rounded-lg border border-slate-200 text-[10px] font-medium text-slate-600 hover:border-slate-400 transition-all duration-150 active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
            [disabled]="currentPage === 1" (click)="prevPage()">
            <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-3 h-3">
              <path stroke-linecap="round" stroke-linejoin="round" d="M10.5 19.5 3 12m0 0 7.5-7.5M3 12h18"/>
            </svg>
            Previous
          </button>
          <div class="flex items-center gap-1">
            <button *ngFor="let p of visiblePages"
              class="w-7 h-7 rounded-lg text-[10px] font-medium transition-colors"
              [class.bg-slate-100]="p === currentPage"
              [class.text-slate-800]="p === currentPage"
              [class.text-slate-400]="p !== currentPage"
              [class.hover:bg-slate-50]="p !== currentPage && p !== -1"
              [class.cursor-default]="p === -1"
              [disabled]="p === -1"
              (click)="p !== -1 && goToPage(p)">{{ p === -1 ? '...' : p }}</button>
          </div>
          <button class="flex items-center gap-1.5 h-7 px-3 rounded-lg border border-slate-200 text-[10px] font-medium text-slate-600 hover:border-slate-400 transition-all duration-150 active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
            [disabled]="currentPage === totalPages" (click)="nextPage()">
            Next
            <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-3 h-3">
              <path stroke-linecap="round" stroke-linejoin="round" d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3"/>
            </svg>
          </button>
        </div>

      </div>
    </div>

    <footer class="h-6 bg-[#434B57] flex items-center justify-center flex-shrink-0">
      <span class="text-[10px] text-white">© Developed by : Software Development Centre, Kristu Jayanti (Deemed to be University), Bangalore</span>
    </footer>
  </div>
  <!-- /BELOW HEADER -->
</div>
